<script setup lang="ts">
import { useForm } from '@inertiajs/vue3'
import { LockKeyhole, LogIn } from '@lucide/vue'

const form = useForm({ email: '', password: '', remember: false })
function submit(): void { form.post(route('login.store'), { onFinish: () => form.reset('password') }) }
</script>
<template><div class="flex min-h-screen items-center justify-center bg-background px-4 py-8"><main class="w-full max-w-md rounded-3xl border bg-card p-6 shadow-xl shadow-primary/5"><div class="flex size-14 items-center justify-center rounded-2xl bg-primary text-primary-foreground"><LockKeyhole class="size-7" /></div><p class="mt-6 text-xs font-semibold uppercase tracking-wider text-primary">Inventaris Pabrik</p><h1 class="mt-1 text-3xl font-bold">Hanya Input Aja</h1><p class="mt-2 text-sm text-muted-foreground">Masuk untuk mengelola dan melihat data aset.</p><form class="mt-7 space-y-5" @submit.prevent="submit"><div><label for="email" class="mb-2 block text-sm font-medium">Email</label><input id="email" v-model="form.email" type="email" autocomplete="email" class="w-full rounded-xl border bg-background px-4 py-3 outline-none ring-primary focus:ring-2" placeholder="nama@perusahaan.com"><p v-if="form.errors.email" class="mt-1 text-sm text-red-600">{{ form.errors.email }}</p></div><div><label for="password" class="mb-2 block text-sm font-medium">Password</label><input id="password" v-model="form.password" type="password" autocomplete="current-password" class="w-full rounded-xl border bg-background px-4 py-3 outline-none ring-primary focus:ring-2"><p v-if="form.errors.password" class="mt-1 text-sm text-red-600">{{ form.errors.password }}</p></div><label class="flex items-center gap-3 text-sm"><input v-model="form.remember" type="checkbox" class="size-4 accent-primary">Ingat saya di perangkat ini</label><button type="submit" :disabled="form.processing" class="flex w-full items-center justify-center gap-2 rounded-xl bg-primary px-4 py-3 font-semibold text-primary-foreground disabled:opacity-60"><LogIn class="size-4" />{{ form.processing ? 'Memproses...' : 'Masuk' }}</button></form></main></div></template>
